// R784: the worship-site strings - the print's
// place-of-worship reads, the prose under the
// five clerical charts (pp. 121-122). The kind
// codes and the cleric-gender grid pin in
// rules/worshipsites.h; the strings ride here,
// one row per deity in the registry order. The
// compilation's Hanali row carries Solonor's
// cells wholesale; the print's fountain-or-spring
// stands. Erevan's read rides the print's own
// "can by worshiped" typo in the prose.
inline const char* uscWorshipSite(int i) {
    static const char* const W[23] = {
        "battlefield",   // Clangeddin
        "underground temple",   // Vergadain
        "underground temple",   // Dumathoin
        "underground temple",   // Abbathor
        "underground temple",   // Berronar
        "open hilltops",   // Aerdrie
        "never the same place twice",   // Erevan
        "deep forest",   // Solonor
        "by a fountain or spring",   // Hanali
        "small grove",   // Labelas
        "open field",   // Sheela
        "anywhere",   // Arvoreen
        "the home",   // Cyrrollalee
        "anywhere",   // Brandobaris
        "forest clearing",   // Baervan
        "underground cavern",   // Urdlen
        "subterranean temple",   // Segojan
        "underground forge",   // Flandal
        "battlefield",   // Bahgtru
        "anywhere",   // Shargaas
        "anywhere",   // Ilneval
        "underground crypt",   // Yurtrus
        "in a temple within a cave",   // Luthic
    };
    if (i < 0) i = 0;
    if (i > 22) i = 22;
    return W[i];
}
}   // namespace rules

// ---- R784: the worship-site strings block ----
// THE STRINGS BLOCK - the authored seam the
// pin mirror cannot see (the R782 site-block
// precedent): every worship-site string the
// uascharts.h accessor returns matches the
// print read, row for row, fail-on-wrong via
// the tiny in-header string equality. This
// printf carries no census marker (the census
// counts the pin audit alone; a bad here
// still fails the battery by the return)
{
    using namespace rules;
    static const char* const want[23] = {
        "battlefield",
        "underground temple",
        "underground temple",
        "underground temple",
        "underground temple",
        "open hilltops",
        "never the same place twice",
        "deep forest",
        "by a fountain or spring",
        "small grove",
        "open field",
        "anywhere",
        "the home",
        "anywhere",
        "forest clearing",
        "underground cavern",
        "subterranean temple",
        "underground forge",
        "battlefield",
        "anywhere",
        "anywhere",
        "underground crypt",
        "in a temple within a cave",
    };
    int bad = 0;
    for (int i = 0; i < 23; ++i)
        if (!uscStrEq(uscWorshipSite(i), want[i]))
            ++bad;
    printf("R784 worship site strings: bad %d\n", bad);
    if (bad) return 1;
}
